args.sparql:
SELECT ?mother ?motherLabel WHERE {
  dbr:Henry_I_of_Cyprus dbp:mother ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = "en") }
}

SELECT ?grandmother ?grandmotherLabel WHERE {
  dbr:Alice_of_Champagne dbp:mother ?grandmother .
  OPTIONAL { ?grandmother rdfs:label ?grandmotherLabel . FILTER(lang(?grandmotherLabel) = "en") }
}

SELECT ?grandmother ?grandmotherLabel WHERE {
  dbr:Henry_I_of_Cyprus dbp:mother ?mother .
  ?mother dbp:mother ?grandmother .
  OPTIONAL { ?grandmother rdfs:label ?grandmotherLabel . FILTER(lang(?grandmotherLabel) = "en") }
}

SELECT ?grandmother ?grandmotherLabel WHERE {
  dbr:Henry_I_of_Cyprus dbp:mother ?mother .
  ?mother dbp:mother ?grandmother .
  OPTIONAL { ?grandmother rdfs:label ?grandmotherLabel . FILTER(lang(?grandmotherLabel) = "en") }
}

